// Pure staging model for grid edits. Edits are staged locally, reviewed as SQL
// (generated by the backend), and committed in one transaction. Undo/redo works
// on the staged state only.
import type { ColumnMeta, RowChange, Value } from './types';
import { valuesEqual } from './value';

export interface StagedState {
  /** row index → column name → new value */
  edits: Record<number, Record<string, Value>>;
  /** indices of existing rows marked for deletion */
  deleted: number[];
  /** new rows: column name → value */
  inserted: Record<string, Value>[];
}

export const emptyStaged = (): StagedState => ({ edits: {}, deleted: [], inserted: [] });

export function pendingCount(s: StagedState): number {
  return Object.values(s.edits).reduce((n, r) => n + (Object.keys(r).length > 0 ? 1 : 0), 0) + s.deleted.length + s.inserted.length;
}

export function setCell(s: StagedState, row: number, col: string, value: Value, original: Value): StagedState {
  const edits = { ...s.edits, [row]: { ...(s.edits[row] ?? {}) } };
  if (valuesEqual(value, original)) delete edits[row][col];
  else edits[row][col] = value;
  if (Object.keys(edits[row]).length === 0) delete edits[row];
  return { ...s, edits };
}

export function toggleDelete(s: StagedState, rows: number[]): StagedState {
  const set = new Set(s.deleted);
  const allDeleted = rows.every((r) => set.has(r));
  rows.forEach((r) => (allDeleted ? set.delete(r) : set.add(r)));
  return { ...s, deleted: [...set].sort((a, b) => a - b) };
}

export function addRow(s: StagedState, values: Record<string, Value> = {}): StagedState {
  return { ...s, inserted: [...s.inserted, values] };
}

export function setInsertedCell(s: StagedState, i: number, col: string, v: Value): StagedState {
  const inserted = s.inserted.map((r, idx) => (idx === i ? { ...r, [col]: v } : r));
  return { ...s, inserted };
}

/** Remove a column from a staged new row, so the INSERT omits it and the column DEFAULT applies. */
export function unsetInsertedCell(s: StagedState, i: number, col: string): StagedState {
  const inserted = s.inserted.map((r, idx) => {
    if (idx !== i) return r;
    const next = { ...r };
    delete next[col];
    return next;
  });
  return { ...s, inserted };
}

export function removeInserted(s: StagedState, i: number): StagedState {
  return { ...s, inserted: s.inserted.filter((_, idx) => idx !== i) };
}

/**
 * Build backend RowChanges. Requires a key (primary key columns); without one,
 * updates/deletes are refused rather than risking multi-row matches.
 */
export function buildChanges(s: StagedState, columns: ColumnMeta[], rows: Value[][], keyColumns: string[]): RowChange[] {
  const idx = (name: string) => columns.findIndex((c) => c.name === name);
  if ((Object.keys(s.edits).length > 0 || s.deleted.length > 0) && keyColumns.length === 0) {
    throw new Error('This table has no primary key, so rows cannot be safely identified. Edit it with SQL instead.');
  }
  const keyOf = (r: number): [string, Value][] => keyColumns.map((k) => [k, rows[r][idx(k)]]);
  const out: RowChange[] = [];
  for (const r of s.deleted) {
    out.push({ op: 'delete', key: keyOf(r), original: [] });
  }
  for (const [rs, cols] of Object.entries(s.edits)) {
    const r = Number(rs);
    if (s.deleted.includes(r)) continue;
    const changes = Object.entries(cols) as [string, Value][];
    if (changes.length === 0) continue;
    const original = changes.map(([c]) => [c, rows[r][idx(c)]] as [string, Value]);
    out.push({ op: 'update', key: keyOf(r), original, changes });
  }
  for (const ins of s.inserted) {
    out.push({ op: 'insert', values: Object.entries(ins) });
  }
  return out;
}

/** Simple bounded undo stack for staged state. */
export class History<T> {
  private past: T[] = [];
  private future: T[] = [];
  constructor(private limit = 200) {}
  push(prev: T) {
    this.past.push(prev);
    if (this.past.length > this.limit) this.past.shift();
    this.future = [];
  }
  undo(current: T): T | undefined {
    const p = this.past.pop();
    if (p !== undefined) this.future.push(current);
    return p;
  }
  redo(current: T): T | undefined {
    const f = this.future.pop();
    if (f !== undefined) this.past.push(current);
    return f;
  }
  clear() {
    this.past = [];
    this.future = [];
  }
}
